// === Tab: Variables ===
/****************************************************************************************************
Electron Simulator 1.0

Author:
	Bryan Brandenburg

Fork of:	
Magical trail shader

Original Author:
  Jason Labbe

Site:
  jasonlabbe3d.com

Controls:
	- Hold the middle mouse button to fade away particles.
	- Press the left mouse button to pause display and remove interface.
	- Press the right mouse button to display the underlying particle system.
	- Press h or H key to hide interface
	- Press p or P key to pause screen (while hiding interface)
*****************************************************************************************************/

//***************************************************************************************************
// Program Variables
//***************************************************************************************************

const MAX_PARTICLE_COUNT = 36*2;
const MAX_TRAIL_COUNT = 66;
const MINIMUM_PARTICLE_VELOCITY = 0.1/2;

const SCREEN_WIDTH = 2300;
const SCREEN_CENTER_X = SCREEN_WIDTH / 2;
const SCREEN_HEIGHT = 1200;
const SCREEN_CENTER_Y = SCREEN_HEIGHT / 2;

const ANGLE_X_SLIDER_X = 100;
const ANGLE_X_SLIDER_Y = 350;
const DISTANCE_BETWEEN_SLIDER_Y = 100;
const ANGLE_Y_SLIDER_X = ANGLE_X_SLIDER_X;
const ANGLE_Y_SLIDER_Y = ANGLE_X_SLIDER_Y + DISTANCE_BETWEEN_SLIDER_Y;
const ANGLE_ATOM_SLIDER_X = ANGLE_X_SLIDER_X;
const ANGLE_ATOM_SLIDER_Y = ANGLE_Y_SLIDER_Y + DISTANCE_BETWEEN_SLIDER_Y;

const X_TEXT_SLIDER_Y = 320;
const Y_TEXT_SLIDER_Y = X_TEXT_SLIDER_Y + DISTANCE_BETWEEN_SLIDER_Y;
const ATOM_TEXT_SLIDER_Y = Y_TEXT_SLIDER_Y + DISTANCE_BETWEEN_SLIDER_Y;

const SLIDER_WINDOW_X = 10;
const SLIDER_WINDOW_Y = 10;
const SLIDER_WINDOW_WIDTH = 500;
const SLIDER_WINDOW_HEIGHT = 660;

const SLIDER_START_X = 0;
const SLIDER_END_X = 255;

const SLIDER_WIDTH = '300px';

const ANGLE_X_DELTA = 9;
const ANGLE_Y_DELTA = 12;
const ANGLE_ATOM_DELTA = 0;
const MAX_DEGREES = 360;

var angleXDelta = 9;
var angleYDelta = 12;
var angleAtomSlider = 0;

var colorScheme = ["#E69F66", "#DF843A", "#D8690F", "#B1560D", "#8A430A"];
var shaded = true;
var soundOn = false;
var screenPause = false;
var hideInterface = false;
var pauseCountdown = 0;
var theShader;
var shaderTexture;
var trail = [];
var particles = [];
var x = 0;
var y = 0;
var lastX = 0;
var lastY = 0;
var angleX = 0;
var angleY = 0;
var velocityX = 0;
var velocityY = 0;
var angleAtom = 0;
var windowAlpha;

let myFont;

// oscillators
let chord = []
let root = 19*6
let major = [ 2, 4, 8 ]
let minor = [ 1, 3 ,5 ]
let n = 360;
let w =SCREEN_WIDTH;

//***************************************************************************************************
// End Electron Simulator
//***************************************************************************************************

// === Tab: Setup ===
//***************************************************************************************************
// Preload Shader
//***************************************************************************************************

function preload() {
	// Load Particle Shader
	theShader = createShader(vertShader, fragShader);

	// Load font
	myFont = loadFont('https://openprocessing.org/sketch/1055183/files/Roboto-Medium.ttf');

} // end preload()

//***************************************************************************************************
// Setup
//***************************************************************************************************

function setup() {

	pixelDensity(1); // can put on slider (1-5)

	let canvas = createCanvas(
		windowWidth, windowHeight, WEBGL);

	// Removes right-click menu.
	canvas.canvas.oncontextmenu = () => false;

	noCursor();

	// create sliders
	xSlider = createSlider(SLIDER_START_X, SLIDER_END_X, 128);
	xSlider.position(ANGLE_X_SLIDER_X, ANGLE_X_SLIDER_Y);
	xSlider.style('width', SLIDER_WIDTH);
	xSlider.opacity = 0.5;
	ySlider = createSlider(SLIDER_START_X, SLIDER_END_X, 128);
	ySlider.position(ANGLE_Y_SLIDER_X, ANGLE_Y_SLIDER_Y);
	ySlider.style('width', '300px');
	atomSlider = createSlider(SLIDER_START_X, SLIDER_END_X, 128);
	atomSlider.position(ANGLE_ATOM_SLIDER_X, ANGLE_ATOM_SLIDER_Y);
	atomSlider.style('width', '300px');

	shaderTexture = createGraphics(SCREEN_WIDTH, SCREEN_HEIGHT, WEBGL);
	shaderTexture.noStroke();

	setupSound();

} /* end setup() */

// === Tab: Draw ===
//***************************************************************************************************
// Main Drawing Loop
//***************************************************************************************************

function draw() {

	angleXDelta = xSlider.value() / 25 + 1;
	angleYDelta = ySlider.value() / 25 + 2;
	angleAtomSlider = atomSlider.value();

	//***************************************************************************************************
	// Update Screen?
	//***************************************************************************************************

	if ((pauseCountdown || !screenPause) || (hideInterface && !screenPause)) {
		if (pauseCountdown) pauseCountdown--;
		cursor(ARROW);
		if ((angleAtom += ANGLE_ATOM_DELTA) > MAX_DEGREES) angleAtom = 0;
		if ((angleX += angleXDelta) > MAX_DEGREES) angleX = 0;
		if ((angleY += angleYDelta) > MAX_DEGREES) angleY = 0;

		let a = (angleX * TWO_PI) / MAX_DEGREES;
		let b = (angleY * TWO_PI) / MAX_DEGREES;
		//print("f is " + a + " and i is " + angleX);

		// save coordinates for computing particle velocities
		lastX = x;
		lastY = y;

		// compute x coordinate of particle
		x = (cos(a) * (SCREEN_WIDTH / 4));
		y = (sin(b) * (SCREEN_HEIGHT / 4));

		let radians = (angleAtom * TWO_PI) / MAX_DEGREES;
		x = x + (width / 2);
		y = y + (height / 2);

		// create velocity vector based on vector between last particle and current particle
		velocityX = (lastX - x) * .9;
		velocityY = (lastY - y) * .9;

		// clear background screen
		background(0);
		noStroke();

		// Trim end of trail.
		trail.push([x, y]); // Use electron position

		let removeCount = 1;
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == CENTER) {
			removeCount++;
		}

		for (let i = 0; i < removeCount; i++) {
			if (trail.length == 0) {
				break;
			}

			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) || trail.length > MAX_TRAIL_COUNT) {
				trail.splice(0, 1);
			}
		}

		//***************************************************************************************************
		// Spawn particles
		//***************************************************************************************************

		if (trail.length > 1 && particles.length < MAX_PARTICLE_COUNT) {
			//	let mouse = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));	// Use mouse x,y
			let mouse = new p5.Vector(x, y); // Use electron position
			mouse.sub((window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY))));
			if (mouse.mag() > 10) {
				mouse.normalize();
				particles.push(new Particle(x, y, velocityX, velocityY));
			}
		}

		translate(-width / 2, -height / 2);

		//***************************************************************************************************
		// Move and kill particles
		//***************************************************************************************************

		for (let i = particles.length - 1; i > -1; i--) {
			particles[i].move();
			if (particles[i].vel.mag() < MINIMUM_PARTICLE_VELOCITY) {
				particles.splice(i, 1);
			}
		}

		if (shaded) {

			//***************************************************************************************************
			// Display shader
			//***************************************************************************************************
			shaderTexture.shader(theShader);

			let data = serializeSketch();

			theShader.setUniform("resolution", [width, height]);
			theShader.setUniform("trailCount", trail.length);
			theShader.setUniform("trail", data.trails);
			theShader.setUniform("particleCount", particles.length);
			theShader.setUniform("particles", data.particles);
			theShader.setUniform("colors", data.colors);

			shaderTexture.rect(0, 0, width, height);
			texture(shaderTexture);

			rect(0, 0, width, height);
		} else {

			//***************************************************************************************************
			// Display points
			//***************************************************************************************************
			stroke(255, 200, 0);
			for (let i = 0; i < particles.length; i++) {
				point(particles[i].pos.x, particles[i].pos.y);
			}

			//***************************************************************************************************
			// Display trail
			//***************************************************************************************************
			stroke(0, 255, 255);
			for (let i = 0; i < trail.length; i++) {
				point(trail[i][0], trail[i][1]);
			}
		}
	} // end if(screenPause)
	else noCursor();

	DrawSliderControlBox();
	doSound();
	warpOscillator(x*6, y*4);
} /* end Draw() */

// === Tab: Sliders ===
//***************************************************************************************************
// Draw Slider Controls
//***************************************************************************************************
function DrawSliderControlBox() {
	stroke('black');
	mouseMoved();
	let c = color('hsba(160, 100%, 50%, windowAlpha)');
	let fontColor = color('hsba(160, 100%, 50%, windowAlpha)');

	if (windowAlpha > 0) {
		c = color('hsba(160, 100%, 50%, 0.8)');
		fontColor = color('hsba(255, 100%, 50%, 0.8)');
	} else {
		c = color('hsba(160, 100%, 50%, 0.1)');
		fontColor = color('hsba(255, 100%, 50%, 0.1)');
	}

	if (!hideInterface) {
		if ((pauseCountdown || !screenPause)) {
			// Draw slider control box
			/*
			fill(c);
			rect(10, 10, 530, 600, 50, 50, 50, 50);
			// Draw Interface Control Box
			fill(c);
			rect(width - width / 6 - 10, height - height / 6 * 2 - 10, width / 6 - 10, height / 3 - 10, 50, 50, 50, 50);
*/
			// Slider Title
			fill(fontColor);
			textAlign(CENTER);
			textFont(myFont);
			textSize(110);
			text("Electron", 266, 120);
			text("Simulator", 266, 250);

			// Slider names
			fill(fontColor);
			textSize(42);

			textAlign(LEFT);
			text("Period X", 40, X_TEXT_SLIDER_Y);
			text("Period Y", 40, Y_TEXT_SLIDER_Y);
			text("Atom Rotation", 40, ATOM_TEXT_SLIDER_Y);

			textAlign(RIGHT);

			let iTemp = 5;

			iTemp = round(angleXDelta);
			var string = nf(iTemp, 2, 0);
			if (angleXDelta > 9) text(nf(iTemp, 1, 0), 500, X_TEXT_SLIDER_Y + 50);
			else text(nf(iTemp, 1, 0), 500, X_TEXT_SLIDER_Y + 50);
			textAlign(RIGHT);

			iTemp = round(angleYDelta);
			string = nf(iTemp, 2, 0);
			if (angleYDelta > 9) text(nf(iTemp, 1, 0), 500, Y_TEXT_SLIDER_Y + 50);
			else text(nf(iTemp, 1, 0), 500, Y_TEXT_SLIDER_Y + 50);
			textAlign(RIGHT);

			iTemp = round(angleAtomSlider);
			string = nf(iTemp, 2, 0);
			if (angleAtomSlider > 9) text(nf(iTemp, 1, 0), 500, ATOM_TEXT_SLIDER_Y + 50);
			else text(nf(iTemp, 1, 0), 500, ATOM_TEXT_SLIDER_Y + 50);
		}
	}
}

// === Tab: Mouse ===
//***************************************************************************************************
// MousePressed
//***************************************************************************************************

function mousePressed() {
	if (mouseButton == RIGHT) {
		shaded = !shaded;
	}
	if ((mouseButton == LEFT) && (windowAlpha == 0.0)) {
		screenPause = true;
		pauseCountdown = 2;
		xSlider.hide();
		ySlider.hide();
		atomSlider.hide();
	}
//	mousePressedSound();
} // end MousePressed()

function mouseMoved() {
	if (((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > SLIDER_WINDOW_X) && ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < (SLIDER_WINDOW_X + SLIDER_WINDOW_WIDTH)) && ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > SLIDER_WINDOW_Y) && ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < (SLIDER_WINDOW_Y + SLIDER_WINDOW_HEIGHT)))
		windowAlpha = 0.5;
	else
		windowAlpha = 0.0;
}

function mouseReleased() {
	screenPause = false;
	pauseCountdown = 0;
	xSlider.show();
	ySlider.show();
	atomSlider.show();
//	mouseReleasedSound();
}

// === Tab: Keyboard ===
function keyPressed() {
	if ((key == 'h') || (key == 'H')) {
		// Unhide Interface
		if (hideInterface == true) {
			xSlider.show();
			ySlider.show();
			atomSlider.show();
			hideInterface = false;
		}
		// Hide Interface
		else {
			xSlider.hide();
			ySlider.hide();
			atomSlider.hide();
			hideInterface = true;
		}
	}
	if ((key == 'p') || (key == 'P')) {
		// Unpause
		if (screenPause == true) {
			screenPause = false;
			pauseCountdown = 0;
			if (!hideInterface) {
				xSlider.show();
				ySlider.show();
				atomSlider.show();
			}
		}
		// Pause
		else {
			screenPause = true;
			pauseCountdown = 2;
			xSlider.hide();
			ySlider.hide();
			atomSlider.hide();
		}
	}

	if ((key == 's') || (key == 'S')) {
		// Sound Off
		if (soundOn) {
			soundOn = false;
			for (let i = 0; i < chord.length; i++) {
				chord[i].amp(3, 0.5)
				chord[i].stop()
			}
		} else {
			soundOn = true;
		}
	}
}

// === Tab: Serialize ===
//***************************************************************************************************
// SerializeSketch map particles to new coordinate system and multiply by mass and velocity
//***************************************************************************************************

function serializeSketch() {
	data = {
		"trails": [],
		"particles": [],
		"colors": []
	};

	for (let i = 0; i < trail.length; i++) {
		data.trails.push(
			map(trail[i][0], 0, width, 0.0, 1.0),
			map(trail[i][1], 0, height, 1.0, 0.0));
	}

	for (let i = 0; i < particles.length; i++) {
		data.particles.push(
			map(particles[i].pos.x, 0, width, 0.0, 1.0),
			map(particles[i].pos.y, 0, height, 1.0, 0.0),
			particles[i].mass * particles[i].vel.mag() / 100)

		let itsColor = colorScheme[particles[i].colorIndex];
		data.colors.push(red(itsColor), green(itsColor), blue(itsColor));
	}

	return data;
}

// === Tab: Particle ===
  //***************************************************************************************************
  // Main Particle handler
  //***************************************************************************************************

  const MAX_VELOCITY = 25;
  const VELOCITY_MULTIPLIER = 10;
  const PARTICLE_MASS = 10;
  const AIR_DRAG_MIN = 0.42 * 1.01;
  const AIR_DRAG_MAX = 0.88 * 1.01;

  function Particle(x, y, vx, vy) {
  	this.pos = new p5.Vector(x, y);
  	this.vel = new p5.Vector(vx, vy);
  	this.vel.mult(VELOCITY_MULTIPLIER);
  	this.mass = random(1, PARTICLE_MASS);
  	this.airDrag = random(AIR_DRAG_MIN, AIR_DRAG_MAX);
  	this.colorIndex = int(random(colorScheme.length));

  	this.move = function() {
  		this.vel.mult(this.airDrag);
  		this.pos.add(this.vel);
  	}
  } /* end Particle() */

// === Tab: Shader ===
//***************************************************************************************************
// Particle Shader
//***************************************************************************************************

let vertShader = `
	precision highp float;

	attribute vec3 aPosition;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`;

let fragShader = `
	precision highp float;

	uniform vec2 resolution;
	uniform int trailCount;
	uniform vec2 trail[${MAX_TRAIL_COUNT}];
	uniform int particleCount;
	uniform vec3 particles[${MAX_PARTICLE_COUNT}];
	uniform vec3 colors[${MAX_PARTICLE_COUNT}];

	void main() {
			vec2 st = gl_FragCoord.xy / resolution.xy;  // Warning! This is causing non-uniform scaling.

			float r = 0.0;
			float g = 0.0;
			float b = 0.0;

			for (int i = 0; i < ${MAX_TRAIL_COUNT}; i++) {
				if (i < trailCount) {
					vec2 trailPos = trail[i];
					float value = float(i) / distance(st, trailPos.xy) * 0.00015;  // Multiplier may need to be adjusted if max trail count is tweaked.
					g += value * 0.5;
					b += value;
				}
			}

			float mult = 0.00005;

			for (int i = 0; i < ${MAX_PARTICLE_COUNT}; i++) {
				if (i < particleCount) {
					vec3 particle = particles[i];
					vec2 pos = particle.xy;
					float mass = particle.z;
					vec3 color = colors[i];

					r += color.r / distance(st, pos) * mult * mass;
					g += color.g / distance(st, pos) * mult * mass;
					b += color.b / distance(st, pos) * mult * mass;
				}
			}

			gl_FragColor = vec4(r, g, b, 1.0);
	}
`;

// === Tab: Oscillator ===
/*jshint esversion: 6 */

// setup and draw functions ---

function setupSound() {

  // initialize oscillators
  if (n < 32) {
    for (let i = 0; i < 3; i++)
    	chord[i] = new p5.TriOsc()
  } else {
    for (let i = 0; i < 3; i++)
    	chord[i] = new p5.SinOsc()
  }

  // initialize with major chord intervals
  for (let i = 0; i < chord.length; i++) {
    	chord[i].freq(major[i] * root)
        chord[i].amp(0.0)
  		chord[i].stop()
  }
} // end setupSound()


function warpOscillator(x,y) {
  // uses max dist to determine the frequency distortion

  let bias = 0
  for (let i = 0; i < n; i++)
  	bias = max(bias, dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), x, y))

  for (let i = 0; i < chord.length; i++)
    chord[i].freq(map(bias, w, 0, major[i], minor[i]) * root)
} // end warpOscillator()
/*
function keyPressed() {
  // toggles synths on

  for (let i = 0; i < chord.length; i++) {
    chord[i].start()
    chord[i].amp(0.3, 0.5)
  }
}
function keyReleased() {
  // toggles synths off

  for (let i = 0; i < chord.length; i++) {
    chord[i].amp(0.0, 0.5)
    chord[i].stop()
  }
}
*/

function doSound() {
  // toggles synths on
	if(!soundOn)
		return;

  for (let i = 0; i < chord.length; i++) {
    chord[i].start()
    chord[i].amp(9, 0.5)
  }
} // end doSound()

